    const std::vector<AlchemyKettleMotion> g_AlchemyKettleMotions = {
        {false, "animations/assets/alchemy_kettle/alchemy_pot_move_up.caf", 2.500000238418579F, 0.3036667F, 0.6089333F},
        {true, "animations/assets/alchemy_kettle/alchemy_pot_move_down.caf", 3.433333396911621F, 0.4651942F, 0.6578156F},
    };

    const AlchemyKettleMotion *FindAlchemyKettleMotion(bool onFire) {
        for (const auto &motion : g_AlchemyKettleMotions)
            if (motion.onFire == onFire)
                return &motion;
        return nullptr;
    }

    const AlchemyAnimationEvent *FindAlchemyAnimationEvent(std::string_view clip, std::string_view name) {
        const AlchemyAnimationEvent *result = nullptr;
        for (const auto &event : g_AlchemyAnimationEvents) {
            if (event.clip != clip || event.name != name)
                continue;
            if (result != nullptr)
                return nullptr;
            result = &event;
        }
        return result;
    }

    const AlchemyAnimationClip *FindAlchemyAnimationClip(std::string_view name) {
        const auto found = std::lower_bound(g_AlchemyAnimationClips.begin(), g_AlchemyAnimationClips.end(), name, [](const AlchemyAnimationClip &clip, std::string_view key) {
            return clip.name < key;
        });
        return found != g_AlchemyAnimationClips.end() && found->name == name ? &*found : nullptr;
    }
